$path=Join-Path $PSScriptRoot '..\admin-panel\app\page.tsx';$content=[IO.File]::ReadAllText($path)
$content=$content.Replace('[bookPreviewOpen,setBookPreviewOpen]=useState(false),','[bookPreviewOpen,setBookPreviewOpen]=useState(false),[bookLibrarySearch,setBookLibrarySearch]=useState(""),[bookLibraryLanguage,setBookLibraryLanguage]=useState(""),[bookLibraryStatus,setBookLibraryStatus]=useState(""),')
$computeMarker='const bookReadiness=bookUploadProgress||'
$compute='const visibleLibrary=library.filter((book:any)=>(!bookLibraryLanguage||book.languageCode===bookLibraryLanguage)&&(!bookLibraryStatus||(bookLibraryStatus==="published"?book.published!==false:book.published===false))&&(!bookLibrarySearch||`${book.title} ${book.author||""} ${book.category||""} ${book.language||""}`.toLowerCase().includes(bookLibrarySearch.toLowerCase())));'
if(-not $content.Contains($computeMarker)){throw 'Book readiness marker not found'};$content=$content.Replace($computeMarker,$compute+$computeMarker)
$heading='<div className="usersHead"><div><h2>Library Books</h2><p>{library.length} saved language-specific book versions</p></div></div><div className="bookRows">'
$navbar='<div className="usersHead"><div><h2>Library Books</h2><p>{visibleLibrary.length} of {library.length} saved language-specific book versions</p></div></div><div className="bookLibraryNav" style={{display:"grid",gridTemplateColumns:"minmax(190px,1fr) 180px 150px auto",gap:9,alignItems:"end",margin:"12px 0 16px",padding:12,border:"1px solid #d6e5da",borderRadius:13,background:"#f4faf6"}}><label style={{fontSize:10,fontWeight:800}}>Find a book<input aria-label="Search library books" placeholder="Title, author or category..." value={bookLibrarySearch} onChange={e=>setBookLibrarySearch(e.target.value)} style={{width:"100%",marginTop:5,padding:10,border:"1px solid #c7d9cd",borderRadius:9,background:"#fff"}}/></label><label style={{fontSize:10,fontWeight:800}}>Language<select aria-label="Filter books by language" value={bookLibraryLanguage} onChange={e=>setBookLibraryLanguage(e.target.value)} style={{width:"100%",marginTop:5,padding:10,border:"1px solid #c7d9cd",borderRadius:9,background:"#fff"}}><option value="">All languages</option>{bookLanguages.map(item=><option key={item.code} value={item.code}>{item.label}</option>)}</select></label><label style={{fontSize:10,fontWeight:800}}>Status<select aria-label="Filter books by status" value={bookLibraryStatus} onChange={e=>setBookLibraryStatus(e.target.value)} style={{width:"100%",marginTop:5,padding:10,border:"1px solid #c7d9cd",borderRadius:9,background:"#fff"}}><option value="">All status</option><option value="published">Published</option><option value="draft">Draft</option></select></label><button type="button" disabled={!bookLibrarySearch&&!bookLibraryLanguage&&!bookLibraryStatus} onClick={()=>{setBookLibrarySearch("");setBookLibraryLanguage("");setBookLibraryStatus("")}} style={{height:38,padding:"0 13px",border:0,borderRadius:9,background:"#e3eee6",color:"#27513f",fontWeight:800,cursor:"pointer"}}>Clear</button></div><div className="bookRows">'
if(-not $content.Contains($heading)){throw 'Library Books heading not found'};$content=$content.Replace($heading,$navbar)
$oldRows='Array.from(new Set(library.map(book=>book.language||"English"))).sort().map(languageName=><section className="bookLanguageGroup" key={languageName as string}><header><div><b>{languageName as string}</b><small>{library.filter(book=>(book.language||"English")===languageName).length} book(s)</small></div></header>{library.filter(book=>(book.language||"English")===languageName).map(book=>'
$newRows='Array.from(new Set(visibleLibrary.map(book=>book.language||"English"))).sort().map(languageName=><section className="bookLanguageGroup" key={languageName as string}><header><div><b>{languageName as string}</b><small>{visibleLibrary.filter(book=>(book.language||"English")===languageName).length} book(s)</small></div></header>{visibleLibrary.filter(book=>(book.language||"English")===languageName).map(book=>'
if(-not $content.Contains($oldRows)){throw 'Library grouped rows not found'};$content=$content.Replace($oldRows,$newRows)
$content=$content.Replace('{library.length===0&&<p className="empty">No books saved yet.</p>}','{visibleLibrary.length===0&&<p className="empty">{library.length?"No books match these filters.":"No books saved yet."}</p>}')
[IO.File]::WriteAllText($path,$content,[Text.UTF8Encoding]::new($false))
